@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ManageMedicationsScreen(
    onSettings: () -> Unit = {},
    viewModel: DailyListViewModel = viewModel(),
) {
    val medications by viewModel.activeMedications.collectAsState()
    var showAddDialog by remember { mutableStateOf(false) }
    var editingMedication by remember { mutableStateOf<Medication?>(null) }
    var showAbout by remember { mutableStateOf(false) }

    Scaffold(
        topBar = {
            CenterAlignedTopAppBar(
                title = { Text(stringResource(R.string.medications_title)) },
                navigationIcon = {
                    IconButton(onClick = { showAbout = true }) {
                        Icon(Icons.Default.Info, contentDescription = stringResource(R.string.about))
                    }
                },
                actions = {
                    IconButton(onClick = onSettings) {
                        Icon(Icons.Default.Settings, contentDescription = stringResource(R.string.settings_label))
                    }
                },
            )
        },
        floatingActionButton = {
            FloatingActionButton(onClick = { showAddDialog = true }) {
                Icon(Icons.Default.Add, contentDescription = stringResource(R.string.add_a_medication))
            }
        },
    ) { padding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(16.dp),
        ) {
            items(medications) { medication ->
                OutlinedCard(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 8.dp),
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Text(
                            stringResource(R.string.medication_name_dose, medication.name, medication.defaultDose),
                            style = MaterialTheme.typography.bodyLarge,
                            modifier = Modifier.weight(1f),
                        )
                        IconButton(onClick = { editingMedication = medication }) {
                            Icon(
                                Icons.Default.Edit,
                                contentDescription = stringResource(R.string.edit_item_content_desc, medication.name),
                            )
                        }
                    }
                }
            }
        }
    }

    if (showAddDialog) {
        AddMedicationDialog(
            onDismiss = { showAddDialog = false },
            onSubmit = { name, defaultDose, minIntervalMinutes ->
                viewModel.insertMedication(name, defaultDose, minIntervalMinutes)
                showAddDialog = false
            },
        )
    }

    editingMedication?.let { medication ->
        EditMedicationDialog(
            medication = medication,
            onDismiss = { editingMedication = null },
            onSave = { updated ->
                viewModel.updateMedication(updated)
                editingMedication = null
            },
            onDelete = { m ->
                viewModel.archiveMedication(m)
                editingMedication = null
            },
        )
    }

    if (showAbout) {
        AboutDialog(onDismiss = { showAbout = false })
    }
}
